// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "ipt_bdchrgRegNoFileInstYn", fn: function () { return String(String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("bdchrgRegNoFileInstYn")))); } },
        { childId: "ipt_fromWhere", fn: function () { return String(String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("fromWhere")))); } },
        { childId: "ipt_checkIdYn", fn: function () { return String(String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("checkIdYn")))); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = async function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        if ($c.util.getComponent('ipt_fromWhere').getValue() === "login") {
            if ($c.util.getComponent('ipt_checkIdYn').getValue() === "N") {
                $c.util.getComponent('ipt_newYn').setValue("Y");
                scwin.dupCheck.setStyle("display", "none");
                (($c.util.getComponent('ipt_integUsrId')) && ($c.util.getComponent('ipt_integUsrId')).setReadOnly ? ($c.util.getComponent('ipt_integUsrId')).setReadOnly((true) === 'disabled' || (true) === 'readonly' || (true) === 'checked' ? true : (true)) : void 0);
                const div = $("#corpFileList");
                if (div.is(":visible")) {
                    div.setStyle("display", "none");
                } else {
                    div.setStyle("display", "");
                }
            } else {
                $("input[name=ipt_integUsrId]").focus().select();
            }
            $c.util.getComponent('ipt_bdchrgApplTpCd').setValue("N");
            await $c.win.alert("신고담당자(정/부) 등록이 필요합니다.");
        } else {
            $("input[name=ipt_integUsrId]").focus().select();
            $c.util.getComponent('ipt_bdchrgApplTpCd').setValue("R");
        }
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf55001.onpageload' }); }
};

