/**
 * @method
 * @name scwin.registerMember
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.registerMember = async function () {
    /* sdd-asis-lifecycle:begin fn_registerMember — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (!await scwin.chkData()) {
        return false;
    }
    const SendForm = (document.SendForm || { elements: [] });
    const chrg_nm = document.getElementsByName("chrg_nm");
    for (let i = 0; i < chrg_nm.length; i++) {
        if ($c.str.getByteLength($c.util.getComponent(["ipt_telNo1", "ipt_telNo1_2"][i]).getValue()) == 0) {
            $c.util.getComponent(["ipt_telNo1", "ipt_telNo1_2"][i]).setValue("00");
        }
        if ($c.util.getComponent(["ipt_faxNo1", "ipt_faxNo1_2"][i]).getValue() !== "" || $c.util.getComponent(["ipt_faxNo2", "ipt_faxNo2_2"][i]).getValue() !== "" || $c.util.getComponent(["ipt_faxNo3", "ipt_faxNo3_2"][i]).getValue() !== "") {
            document.SendForm.fax_no[i].value = $c.util.getComponent(["ipt_faxNo1", "ipt_faxNo1_2"][i]).getValue() + '-' + $c.util.getComponent(["ipt_faxNo2", "ipt_faxNo2_2"][i]).getValue() + '-' + $c.util.getComponent(["ipt_faxNo3", "ipt_faxNo3_2"][i]).getValue();
        }
        document.SendForm.tel_no[i].value = $c.util.getComponent(["ipt_telNo1", "ipt_telNo1_2"][i]).getValue() + '-' + $c.util.getComponent(["ipt_telNo2", "ipt_telNo2_2"][i]).getValue() + '-' + $c.util.getComponent(["ipt_telNo3", "ipt_telNo3_2"][i]).getValue();
        document.SendForm.encryp_email[i].value = $c.util.getComponent(["ipt_encrypEmail1", "ipt_encrypEmail1_2"][i]).getValue() + '@' + $c.util.getComponent(["ipt_encrypEmail2", "ipt_encrypEmail2_2"][i]).getValue();
        document.SendForm.encryp_cellphone_no[i].value = $c.util.getComponent(["ipt_encrypCellphoneNo1", "ipt_encrypCellphoneNo1_2"][i]).getValue() + "-" + $c.util.getComponent(["ipt_encrypCellphoneNo2", "ipt_encrypCellphoneNo2_2"][i]).getValue() + "-" + $c.util.getComponent(["ipt_encrypCellphoneNo3", "ipt_encrypCellphoneNo3_2"][i]).getValue();
    }
    if (!await $c.win.confirm("신청하시겠습니까?")) {
        return false;
    }
    $c.util.getComponent('txt_spanReq').setLabel("신청 중...");
    $("#aLinkReq").attr("onclick", "return false;");
    scwin.form_SendForm.action = "/register/registerNew.do?method=registerMemberNew";
    scwin.form_SendForm.target = "_self";
    await scwin.tx_fn_registerMember();
    /* sdd-asis-lifecycle:end */
};


