/**
 * @method
 * @name scwin.downloadDoc
 * @author Inswave
 * @date 2026. 09. 29
 * @param docCd fileNm
 * @returns
 * @hidden N
*/
scwin.downloadDoc = async function (docCd, fileNm) {
    /* sdd-asis-lifecycle:begin fn_downloadDoc — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (!await $c.win.confirm(fileNm + " 다운로드 하시겠습니까?")) {
        return;
    }
    const fm = (document.fileDownForm || { elements: [] });
    $c.util.getComponent("dma_registerMemberReq").set("contnId", docCd);
    fm.action = '/main/notice.do?method=downloadFile';
    await scwin.tx_fn_downloadDoc();
    return;
    /* sdd-asis-lifecycle:end */
};


