/**
 * @method
 * @name scwin.checkUsrIdDone
 * @author Inswave
 * @date 2026. 09. 29
 * @param data
 * @returns
 * @hidden N
*/
scwin.checkUsrIdDone = function (data) {
    /* sdd-asis-lifecycle:begin fn_checkUsrId_done — as-is 원문 본문(전환 이관 · 포팅 적용됨) */const result = (typeof data === "string" ? JSON.parse(data) : data);
    $c.util.getComponent('ipt_message').setValue(result.message);
    $c.util.getComponent('ipt_newYn').setValue(result.newYn);
    /* sdd-asis-lifecycle:end */
};

/**
 * @method
 * @name scwin.checkUsrId
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.checkUsrId = async function () {
    const r = await scwin.tx_fn_checkUsrId();
    try {
        scwin.checkUsrIdDone.call(window, JSON.stringify((r && r.responseJSON && (r.responseJSON.body != null ? r.responseJSON.body : r.responseJSON)) || {}));
    }
    catch (_se) {
        await $c.exception.handleError(_se, { notify: 'none', context: 'jldbnf55001.fn_checkUsrId' });
    }
    return r;
};
